mapper.select:
select T1.ENTRUST_ID, T1.ENTRUST_STATUS, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T1.FINPROD_ID, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS, T1.ENTRUST_NUM/100 entrustAmt, T1.PRICE_MODEL, T1.PRICE*100 price, T7.SETTLE_SPREED, T1.VDATE, T1.MDATE, NULLIF(T5.FINISH_AMT,0)*100 finishAmt, round(NULLIF(T5.FINISH_AMT,0)/ NULLIF(T1.ENTRUST_NUM, T1.ENTRUST_AMT),4)*100 transactioncom, T1.REMARK ,T7.FIRST_UNIT_CPRICE firstprice ,T7.FIRST_UNIT_CPRICE2 firstprice2 from ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N})
AND T1.portfolio_id in
#{item}
AND T7.TERM_TYPE = #{termType}
AND T1.PS=#{ps}
AND T1.VDATE >= to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <= to_date(#{endDate},'yyyy-MM-dd')
AND T1.PRICE_MODEL = #{priceModel}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_ID = #{entrustId}
UNION ALL select T1.ENTRUST_ID, T1.ENTRUST_STATUS, T8.REAL_NAME invManagerId, T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T1.FINPROD_ID, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ABBR finprodAbbr, T7.TERM_TYPE termType, T7.TERM_DAYS repoTerm, T1.PS, T1.ENTRUST_NUM/100 entrustAmt, T1.PRICE_MODEL, T1.PRICE*100 price, T7.SETTLE_SPREED, T1.VDATE, T1.MDATE, NULLIF(T5.FINISH_AMT,0)*100 finishAmt, round(NULLIF(T5.FINISH_AMT,0)/ NULLIF(T1.ENTRUST_NUM, T1.ENTRUST_AMT),4)*100 transactioncom, T1.REMARK ,T7.FIRST_UNIT_CPRICE firstprice ,T7.FIRST_UNIT_CPRICE2 firstprice2 from WFL_ETR_ENTRUST T1 INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON T1.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
INNER JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) as FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON T1.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN WFL_ETR_ENTRUST_ADD T7 ON T1.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN SYS_USER T8 ON T1.INV_MANAGER_ID = T8.USER_NAME where T1.FINPROD_TYPE2 in (#{FINPROD_TYPE2_Z},#{FINPROD_TYPE2_N})
AND T1.portfolio_id in
#{item}
AND T7.TERM_TYPE = #{termType}
AND T1.PS=#{ps}
AND T1.VDATE >= to_date(#{startDate},'yyyy-MM-dd')
AND T1.MDATE <= to_date(#{endDate},'yyyy-MM-dd')
AND T1.PRICE_MODEL = #{priceModel}
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.ENTRUST_ID = #{entrustId}

select TEMP.PORTFOLIO_ID, PP.PORTFOLIO_NAME, TEMP.FINPROD_ID, FP.FINPROD_MARKET_ID, FP.FINPROD_ABBR, T4.TYPE_9 secType1, NULLIF(TEMP.AMOUNT, 0) / 100 posStrdPrinAmt, NULLIF(TEMP.AMOUNT04, 0) / 100 pledStrdPrinAmt, NULLIF(TEMP.AMOUNT05, 0) / 100 inStrdPrinAmt, NULLIF(TEMP.AMOUNT06, 0) / 100 outStrdPrinAmt, NULLIF(t7.amount, 0) / 100 avaStrdPrinAmt, MBVI.NETPRICE newPrice, tchl.SEC_ACCT_ID channelId, MBCR.GRADE_RESULT gradeResult, MBCR2.GRADE_RESULT ztgradeResult, FP.REGIST_ORG registOrg, MBVI.LAST_PERIOD lastPeriod, FP.MDATE mdate from ( SELECT PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.FINPROD_ID AS FINPROD_ID, SUM(CASE WHEN PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_05}) THEN NULLIF(PSP.AMOUNT,0) ELSE -1* NULLIF(PSP.AMOUNT,0) END) AS AMOUNT, SUM(NULLIF(CASE WHEN PSP.HODING_TYPE = #{POSITION_TYPE_04} THEN AMOUNT ELSE 0 END , 0)) AS AMOUNT04 , SUM(NULLIF(CASE WHEN PSP.HODING_TYPE = #{POSITION_TYPE_05} THEN AMOUNT ELSE 0 END , 0)) AS AMOUNT05 , SUM(NULLIF(CASE WHEN PSP.HODING_TYPE = #{POSITION_TYPE_06} THEN AMOUNT ELSE 0 END , 0)) AS AMOUNT06 FROM PTL_SEC_POSITION PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.BRANCH =0 AND PSP.HODING_TYPE IN (#{POSITION_TYPE_03}, #{POSITION_TYPE_04}, #{POSITION_TYPE_05}, #{POSITION_TYPE_06}) AND PSP.CDATE = to_date(#{sysDate},'yyyy-MM-dd') GROUP BY PSP.PORTFOLIO_ID , PSP.FINPROD_ID )TEMP LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID = FP.FINPROD_ID left join ( select portfolio_id, finprod_id, sum(t.amount) as amount from etr_sec_position t where 1=1
AND portfolio_id in
#{item}
and cdate = to_date(#{sysDate},'yyyy-MM-dd') and hoding_type = 'E01' group by portfolio_id,finprod_id ) t7 on t7.portfolio_id = TEMP.portfolio_id and t7.finprod_id = TEMP.finprod_id LEFT JOIN ( select SEC_ID, NETPRICE, LAST_PERIOD from ( select ROW_NUMBER() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC) rn, SEC_ID, NETPRICE, LAST_PERIOD from MST_BOND_VALUATION_INFO WHERE VALUE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') ) where rn = 1 ) MBVI ON FP.FINPROD_MARKET_ID = MBVI.SEC_ID left join ( select min(esp.SEC_ACCT_ID) SEC_ACCT_ID, esp.FINPROD_ID, esp.PORTFOLIO_ID FROM etr_sec_position esp inner join fin_product fp on fp.FINPROD_ID = esp.SEC_ACCT_ID and fp.FINPROD_TYPE2 = 'F28' where 1=1
AND esp.portfolio_id in
#{item}
and esp.cdate = to_date(#{sysDate},'yyyy-MM-dd') and esp.hoding_type = 'E01' group by esp.FINPROD_ID,esp.PORTFOLIO_ID ) tchl on tchl.portfolio_id = TEMP.portfolio_id and tchl.finprod_id = TEMP.finprod_id LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC, grade_result DESC, O_TYPE) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID!='22') MBCR ON MBCR.O_CODE = FP.FINPROD_MARKET_ID AND MBCR.NUM = 1 LEFT JOIN (SELECT RANK() OVER(PARTITION BY O_CODE ORDER BY GRADE_DATE DESC, grade_result DESC, O_TYPE) NUM, O_CODE, GRADE_RESULT FROM MST_BOND_CREDIT_RATING WHERE GRADE_DATE <= to_date(#{sysDate},'yyyy-MM-dd') and GRADE_ORG_ID!='22') MBCR2 ON MBCR2.O_CODE = FP.ISSUER AND MBCR2.NUM = 1 where FP.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F01}
AND TEMP.portfolio_id in
#{item}
AND T4.TYPE_9 = #{secType1,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID in
#{item}
